def sorts(net,n):
    bad=[]
    for m in range(1<<n):
        v=[(m>>k)&1 for k in range(n)]
        for (i,j) in net:
            if v[i]>v[j]: v[i],v[j]=v[j],v[i]
        if v!=sorted(v): bad.append(m)
    return bad
for k,net in tmpl.items():
    b=sorts(net,k)
    print(k, "size",len(net), "SORTS" if not b else f"NOT A SORTER: {len(b)} bad inputs e.g. {[(x>>i)&1 for i in range(k)] for x in b[:1]}" if False else ("SORTS" if not b else f"NOT A SORTER ({len(b)} bad inputs, first={b[:3]})"))
